import sys, json, re

# THE CROSS QUESTIONS OF A GRAPH SPACE (graph-space, GH #945). Every question
# arrives on `in_graph` and leaves as exactly one `answer`; it reads this
# space's own store and nothing else -- no source gets a message, so a
# question over a thousand files wakes none of them.
#
# The request: body `{op, args}` (or the arguments beside `op`), hop `op`,
# `op_id`, `caller?`. The answer: route `answer`, hop `op`, `op_id`, `caller`
# mirrored, body `{ok, op, op_id, items, next?, broken, ...}` or `{ok: false,
# op, op_id, error: {code, message}}`. Every answer counts the `broken` edges
# it touched: a broken edge is reported where somebody looks.
#
# Ops: `resolve {name}` (addresses that answer to a name: a module, a
# qualified `<module>:<name>`, or a bare identifier), `callers {addr}`
# (incoming `call`), `dependents {addr, depth <= 3}` (incoming, any kind,
# transitive), `deps {addr}` (outgoing, resolved), `path {from, to, max <= 6}`
# (shortest directed path over resolved edges, met in the middle by two
# `traverse` legs), `similar {addr}` (the `inferred` edges), `broken {}`,
# `stats {}`. Structural ops follow `extracted` edges only; `similar` follows
# only `inferred` ones. Every list is a page: `limit` (default 20, at most
# 50) and `next`, the cursor of the following page.
#
# A QUESTION SEES ITS ROUND (#951). The nodes of an object hive (`ob-`) were
# learned in a round (`sources.audience_set`); a file space's are public in
# the space. The round of a question is `context.audience_now`, else
# `context.audience_set`. An `ob-` source is visible when its round covers the
# question's -- nobody in the question is missing from it -- and no `ob-`
# source is visible to a question without a round. In EVERY answer the hidden
# nodes, the edges from and to hidden sources (and every edge whose target
# names a hidden or unknown `ob-`, in any state), the `resolve` hits, the
# traversal paths through a hidden node and the counters (`broken`, `stats`)
# fall away; a question about a hidden address is answered as one about an
# unknown address. The rounds are read by one more leg of the question's own
# bundle (`sources where audience_set != ''`).
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}


def _int(key, default):
    v = P.get(key, default)
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    try:
        return int(float(v))
    except Exception:
        return default


SCAN = max(100, _int("scan_max", 20000))
TRAVERSE_NODES = max(10, min(5000, _int("traverse_nodes", 2000)))

ME = "query"
OPS = ("resolve", "callers", "dependents", "deps", "path", "similar", "broken", "stats")
LIMIT_DEFAULT = 20
LIMIT_MAX = 50
DEPTH_MAX = 3
PATH_MAX = 6
SOURCE_RE = re.compile(r"^(fh|ob)-[0-9a-f]{12}$")
ADDR_HINT = "(fh|ob)-<12 hex>[#anchor]"
ADDR_RE = re.compile(r"^(fh|ob)-[0-9a-f]{12}(#[^\s#]{1,512})?$")
EDGE_COLS = ["from_addr", "from_source", "kind", "target_name", "to_addr", "to_source",
             "state", "class", "score", "since"]
# What the round filter needs of an edge that is only counted (#951).
ENDS_COLS = ["state", "from_source", "to_source", "to_addr", "target_name"]
# A direct address as a link names it (index's DIRECT_RE): the target of an
# edge that points at an object, whatever became of it.
DIRECT_RE = re.compile(r"^((?:fh|ob)-[0-9a-f]{12})(?:#([^\s#]{1,512}))?$")


# ============================================================ PURE

def round_of(v):
    """A round -- a JSON list of strings (or the list itself) -> the sorted
    set, None when it is no round (unparsable, empty text, not a list of
    strings). `[]` is a round: the empty one."""
    xs = v
    if isinstance(v, str):
        if not v.strip():
            return None
        try:
            xs = json.loads(v)
        except Exception:
            return None
    if not isinstance(xs, list) or not all(isinstance(x, str) for x in xs):
        return None
    return sorted(set(xs))


def covers(row_aud, q):
    """Whether a row learned in round `row_aud` is visible to a question in
    round `q`: nobody in `q` is missing from it (`*` lets everyone in).
    Fail-closed: no round on either side -> False (#951)."""
    row, q = round_of(row_aud), round_of(q)
    if q is None or row is None:
        return False
    if "*" in row:
        return True
    if not q:
        # A roundless question sees only roundless rows: `set() <= row` would
        # let it see every object of every round (#951, fail-closed).
        return not row
    return set(q) <= set(row)


def question_round(context):
    """The round of a question: `audience_now`, else `audience_set`, as its
    canonical text; None for a question without a round."""
    for key in ("audience_now", "audience_set"):
        r = round_of((context or {}).get(key))
        if r is not None:
            return json.dumps(r, separators=(",", ":"))
    return None


def source_of(addr):
    return str(addr or "").split("#", 1)[0].split("@", 1)[0]


def visible_objects(aud_rows, q):
    """The `ob-` sources a question in round `q` may see."""
    return {str(r.get("source") or "") for r in aud_rows
            if str(r.get("source") or "").startswith("ob-")
            and covers(r.get("audience_set"), q)}


def hidden_by(seen):
    """addr -> hidden: every `ob-` address whose source is not in `seen`."""
    def hidden(addr):
        s = source_of(addr)
        return s.startswith("ob-") and s not in seen
    return hidden


def edge_hidden(e, hidden):
    """An edge from or to a hidden source -- and an edge whose `target_name`
    is the direct address of an `ob-` this round may not see, in ANY state.
    By its resolved ends alone a link to a hidden object (resolved, hidden)
    and a link to an object that never was (unresolved, shown) told the two
    apart, and with them whether an object of another round exists: the ids
    are `sha256(name + round)` and so guessable (review O I-1)."""
    if any(hidden(e.get(c)) for c in ("from_source", "from_addr", "to_source", "to_addr")):
        return True
    m = DIRECT_RE.match(str(e.get("target_name") or "").strip())
    return bool(m) and hidden(m.group(1))


def parse_addr(s):
    """An address of this space -> (source, anchor) or None. A version pin
    (`@<hex>`) is dropped: the graph holds the head of every source."""
    if not isinstance(s, str):
        return None
    s = s.strip()
    anchor = ""
    if "#" in s:
        s, anchor = s.split("#", 1)
        if not anchor:
            return None
    if "@" in s:
        s = s.split("@", 1)[0]
    if not SOURCE_RE.match(s):
        return None
    if not ADDR_RE.match(s + ("#" + anchor if anchor else "")):
        return None
    return s, anchor


def page(items, cursor, limit):
    """One page of an ordered list: (items, next). The cursor is the offset
    of the page as text; a malformed one starts at the top."""
    try:
        start = max(0, int(str(cursor or "0")))
    except Exception:
        start = 0
    chunk = items[start:start + limit]
    nxt = str(start + limit) if start + limit < len(items) else ""
    return chunk, nxt


def ends(addr):
    """The columns a structural question walks: node addresses for a node,
    source columns for a source."""
    return ("to_addr", "from_addr") if "#" in addr else ("to_source", "from_source")


def full_path(start, row):
    p = [x for x in (row.get("path") or []) if isinstance(x, str)]
    if not p or p[0] != start:
        p = [start] + p
    node = row.get("node")
    if isinstance(node, str) and p[-1] != node:
        p.append(node)
    return p


def shortest(src, dst, fwd, bwd, max_len):
    """The shortest directed path from `src` to `dst` met in the middle:
    `fwd` the forward traversal from `src`, `bwd` the backward one from
    `dst`. Ties go to the lexically first path."""
    if src == dst:
        return [src]
    a = {src: [src]}
    for r in fwd:
        p = full_path(src, r)
        n = p[-1]
        if n not in a or (len(p), p) < (len(a[n]), a[n]):
            a[n] = p
    b = {dst: [dst]}
    for r in bwd:
        p = full_path(dst, r)
        n = p[-1]
        if n not in b or (len(p), p) < (len(b[n]), b[n]):
            b[n] = p
    best = None
    for n in a:
        if n in b:
            p = a[n] + list(reversed(b[n]))[1:]
            if len(p) - 1 <= max_len and (best is None or (len(p), p) < (len(best), best)):
                best = p
    return best


def dependents_of(rows):
    """Traversal rows -> [{addr, depth}] by depth, then address; each address
    once at its smallest depth."""
    best = {}
    for r in rows:
        n, dep = r.get("node"), r.get("depth")
        if not isinstance(n, str):
            continue
        try:
            dep = int(dep)
        except Exception:
            continue
        if n not in best or dep < best[n]:
            best[n] = dep
    return [{"addr": n, "depth": dep} for n, dep in sorted(best.items(), key=lambda x: (x[1], x[0]))]


# ============================================================ PLUMBING

def emit(msgs):
    for m in msgs:
        if isinstance(m, dict) and not any(k in m for k in ("messages", "system", "attachments")):
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("graph-space/query: %s\n" % reason)
    emit([])


def sel(table, columns, where, limit, order=None):
    a = {"operation": "select", "table": table, "columns": columns, "where": where,
         "limit": int(limit)}
    if order:
        a["order_by"] = [{"col": c, "dir": o} for c, o in order]
    return a


def store(ops, R):
    return {"header": {"route": "query_store", "phase": "answer", "reply_cell": ME,
                       "cur_call": json.dumps(R, sort_keys=True)},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def finish(R, body):
    msg = {"header": {"route": "answer", "op": R["op"], "op_id": R["op_id"],
                      "caller": R.get("caller", "")},
           "messages": [], "op": R["op"], "op_id": R["op_id"]}
    msg.update(body)
    emit([msg])


def fail(R, code, message):
    finish(R, {"ok": False, "error": {"code": code, "message": message}})


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": ""})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(out) == 1:
        next(iter(out.values()))["error_code"] = str(hop.get("error_code") or "")
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return [r for r in p if isinstance(r, dict)] if isinstance(p, list) else []


def paths(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return [r for r in p.get("paths") or [] if isinstance(r, dict)] if isinstance(p, dict) else []


def num(v):
    try:
        return float(v)
    except Exception:
        return 0.0


def count_broken(rs):
    return sum(1 for r in rs if r.get("state") == "broken")


# ============================================================ ASK

def ask(R):
    """The one store bundle a question needs, the rounds of the `ob-` sources
    (`aud`, #951) always among its legs."""
    return legs_of(R) + [("aud", sel("sources", ["source", "audience_set"],
                                     {"audience_set": {"neq": ""}}, SCAN))]


def legs_of(R):
    a, op = R["args"], R["op"]
    if op == "resolve":
        name = str(a.get("name") or "").strip()
        if not name or len(name) > 512:
            fail(R, "bad_request", "resolve takes `name`")
        # The answer echoes the name as text, whatever the asker sent.
        R["args"]["name"] = name
        bare = name.rsplit(":", 1)[-1].rsplit(".", 1)[-1] if (":" in name or "::" in name) else name
        return [("names", sel("names", ["name", "addr", "kind"], {"name": name}, SCAN)),
                ("nodes", sel("nodes", ["addr", "name"], {"name": name}, SCAN)),
                ("brk", sel("edges", ENDS_COLS, {"to_member": bare, "state": "broken"}, SCAN))]
    if op == "broken":
        return [("edges", sel("edges", EDGE_COLS, {"state": "broken"}, SCAN,
                              [("from_addr", "asc"), ("target_name", "asc")]))]
    if op == "stats":
        return [("src", sel("sources", ["source", "tomb"], {}, SCAN)),
                ("nodes", sel("nodes", ["source"], {}, SCAN)),
                ("edges", sel("edges", ["state", "class", "from_source", "to_source", "to_addr",
                                        "target_name"], {}, SCAN))]
    if op == "path":
        f, t = parse_addr(a.get("from")), parse_addr(a.get("to"))
        if not f or not t:
            fail(R, "bad_address", "path takes `from` and `to`, each " + ADDR_HINT)
        try:
            mx = int(a.get("max") if a.get("max") is not None else PATH_MAX)
        except Exception:
            mx = PATH_MAX
        if mx < 1 or mx > PATH_MAX:
            fail(R, "bad_request", "`max` is 1 to %d" % PATH_MAX)
        node_level = bool(f[1] and t[1])
        fa = f[0] + ("#" + f[1] if node_level else "")
        ta = t[0] + ("#" + t[1] if node_level else "")
        src_col, dst_col = ("from_addr", "to_addr") if node_level else ("from_source", "to_source")
        R["args"] = {"from": fa, "to": ta, "max": mx}
        walk = {"state": "resolved", "class": "extracted"}
        fwd_depth = (mx + 1) // 2
        bwd_depth = mx - fwd_depth
        ops = [("fwd", {"operation": "traverse", "table": "edges", "src": src_col,
                        "dst": dst_col, "start": fa, "where": walk, "max_depth": fwd_depth,
                        "max_nodes": TRAVERSE_NODES})]
        if bwd_depth:
            ops.append(("bwd", {"operation": "traverse", "table": "edges", "src": dst_col,
                                "dst": src_col, "start": ta, "where": walk,
                                "max_depth": bwd_depth, "max_nodes": TRAVERSE_NODES}))
        ops.append(("brk", sel("edges", ENDS_COLS, {src_col: fa, "state": "broken"}, SCAN)))
        return ops
    pa = parse_addr(a.get("addr"))
    if not pa:
        fail(R, "bad_address", "%s takes `addr`, %s" % (op, ADDR_HINT))
    addr = pa[0] + ("#" + pa[1] if pa[1] else "")
    R["args"]["addr"] = addr
    to_col, from_col = ends(addr)
    if op == "callers":
        return [("edges", sel("edges", EDGE_COLS, {to_col: addr, "kind": "call",
                                                   "class": "extracted"}, SCAN))]
    if op == "deps":
        return [("edges", sel("edges", EDGE_COLS, {from_col: addr, "class": "extracted"},
                              SCAN))]
    if op == "similar":
        return [("edges", sel("edges", EDGE_COLS, {"from_source": pa[0], "class": "inferred"},
                              SCAN))]
    if op == "dependents":
        try:
            depth = int(a.get("depth") if a.get("depth") is not None else 1)
        except Exception:
            depth = 1
        if depth < 1 or depth > DEPTH_MAX:
            fail(R, "bad_request", "`depth` is 1 to %d" % DEPTH_MAX)
        R["args"]["depth"] = depth
        return [("walk", {"operation": "traverse", "table": "edges", "src": to_col,
                          "dst": from_col, "start": addr,
                          "where": {"state": "resolved", "class": "extracted"},
                          "max_depth": depth, "max_nodes": TRAVERSE_NODES}),
                ("brk", sel("edges", ENDS_COLS, {to_col: addr, "state": "broken"}, SCAN))]
    fail(R, "unknown_op", "this lane serves " + ", ".join(OPS))


def answer(R, lg):
    op, a = R["op"], R["args"]
    limit = R["limit"]
    # The round filter (#951): what this question may see. A question about a
    # hidden address reads nothing -- the answer of an unknown address.
    hidden = hidden_by(visible_objects(rows(lg, "aud"), R.get("round")))
    asked = [a.get(k) for k in ("addr", "from", "to") if isinstance(a.get(k), str)]
    blind = any(hidden(x) for x in asked)

    def seen(cid):
        return [] if blind else [r for r in rows(lg, cid) if not edge_hidden(r, hidden)]

    def walks(cid, start):
        return [] if blind else [r for r in paths(lg, cid)
                                 if not any(hidden(x) for x in full_path(start, r))]

    if op == "resolve":
        hits = {}
        for r in rows(lg, "names"):
            if not hidden(r.get("addr")):
                hits[str(r.get("addr"))] = str(r.get("kind") or "qualified")
        for r in rows(lg, "nodes"):
            if not hidden(r.get("addr")):
                hits.setdefault(str(r.get("addr")), "name")
        items = [{"addr": k, "match": v} for k, v in sorted(hits.items())]
        chunk, nxt = page(items, a.get("cursor"), limit)
        return {"ok": True, "name": a.get("name"), "items": chunk, "next": nxt,
                "broken": len(seen("brk"))}
    if op == "broken":
        items = [{"from": r.get("from_addr"), "kind": r.get("kind"),
                  "target_name": r.get("target_name"), "to": r.get("to_addr") or "",
                  "since": r.get("since") or ""} for r in seen("edges")]
        chunk, nxt = page(items, a.get("cursor"), limit)
        return {"ok": True, "items": chunk, "next": nxt, "broken": len(items)}
    if op == "stats":
        raw_src, raw_nodes, raw_edges = rows(lg, "src"), rows(lg, "nodes"), rows(lg, "edges")
        src = [s for s in raw_src if not hidden(s.get("source"))]
        nodes = [n for n in raw_nodes if not hidden(n.get("source"))]
        edges = seen("edges")
        by_state, by_class = {}, {}
        for e in edges:
            by_state[e.get("state") or ""] = by_state.get(e.get("state") or "", 0) + 1
            by_class[e.get("class") or ""] = by_class.get(e.get("class") or "", 0) + 1
        return {"ok": True, "sources": sum(1 for s in src if not s.get("tomb")),
                "removed": sum(1 for s in src if s.get("tomb")), "nodes": len(nodes),
                "edges": len(edges), "states": by_state, "classes": by_class,
                "truncated": max(len(raw_src), len(raw_nodes), len(raw_edges)) >= SCAN,
                "items": [], "next": "", "broken": by_state.get("broken", 0)}
    if op == "path":
        # The shortest path over what this round may see: a path through a
        # hidden node is no path for it.
        best = shortest(a["from"], a["to"], walks("fwd", a["from"]), walks("bwd", a["to"]),
                        a["max"])
        return {"ok": True, "from": a["from"], "to": a["to"], "found": best is not None,
                "items": best or [], "hops": (len(best) - 1) if best else 0, "next": "",
                "broken": len(seen("brk"))}
    if op == "dependents":
        items = [x for x in dependents_of(walks("walk", a["addr"])) if x["addr"] != a["addr"]]
        chunk, nxt = page(items, a.get("cursor"), limit)
        return {"ok": True, "addr": a["addr"], "depth": a["depth"], "items": chunk,
                "next": nxt, "broken": len(seen("brk"))}
    es = seen("edges")
    if op == "callers":
        live = sorted({r.get("from_addr") for r in es if r.get("state") == "resolved"})
        items = [{"addr": x} for x in live]
    elif op == "deps":
        live = sorted({(r.get("to_addr"), r.get("kind")) for r in es
                       if r.get("state") == "resolved"})
        items = [{"addr": x, "kind": k} for x, k in live]
    else:
        items = sorted(({"addr": r.get("to_addr"), "score": num(r.get("score"))} for r in es),
                       key=lambda x: (-x["score"], str(x["addr"])))
    chunk, nxt = page(items, a.get("cursor"), limit)
    return {"ok": True, "addr": a["addr"], "items": chunk, "next": nxt,
            "broken": count_broken(es)}


# ============================================================ LANES

lane = str(hop.get("route") or "")
op_ = str(hop.get("operation") or "")

if lane == "in_graph":
    op = str(hop.get("op") or d.get("op") or "")
    args = d.get("args") if isinstance(d.get("args"), dict) else {
        k: v for k, v in d.items() if k not in ("op", "messages", "op_id")}
    # The round travels with the question through the store (`cur_call`).
    R = {"op": op, "op_id": str(hop.get("op_id") or ""), "caller": str(hop.get("caller") or ""),
         "args": args, "round": question_round(ctx)}
    try:
        limit = int(args.get("limit") if args.get("limit") is not None else LIMIT_DEFAULT)
    except Exception:
        limit = LIMIT_DEFAULT
    R["limit"] = max(1, min(LIMIT_MAX, limit))
    if not R["op_id"]:
        fail(R, "bad_request", "a question carries hop.op_id")
    if op not in OPS:
        fail(R, "unknown_op", "this lane serves " + ", ".join(OPS))
    ops = ask(R)
    emit([store(ops, R)])

if lane:
    park("unknown lane %r -- dropped" % lane)
if not op_:
    park("a message with neither a lane nor a store answer -- dropped")

try:
    R = json.loads(ctx.get("cur_call") or "null")
except Exception:
    R = None
if not isinstance(R, dict) or not R.get("op_id"):
    park("store answer without its question -- dropped")
lg = legs(d)
bad = sorted(c for c, leg in lg.items() if leg["error_code"])
if bad:
    sys.stderr.write("graph-space/query: store refused %s\n" % ", ".join(bad))
    fail(R, "store_error", "the store refused a read; try again later")
finish(R, answer(R, lg))
